WITH drug1_source AS (
 SELECT concept_id FROM omop.concept WHERE vocabulary_id = 'RxNorm' AND concept_code = '312935'
),
drug1_mapped AS (
 SELECT concept_id_2 AS concept_id FROM drug1_source ds JOIN omop.concept_relationship cr ON ds.concept_id = cr.concept_id_1 WHERE cr.relationship_id = 'Maps to'
),
drug1_concepts AS (
 SELECT DISTINCT ca.descendant_concept_id AS concept_id FROM drug1_mapped dm JOIN omop.concept c ON dm.concept_id = c.concept_id JOIN omop.concept_ancestor ca ON c.concept_id = ca.ancestor_concept_id
),
drug1_exposures AS (
 SELECT de.person_id, de.drug_exposure_start_date AS start_date FROM omop.drug_exposure de JOIN drug1_concepts d1 ON de.drug_concept_id = d1.concept_id
),
drug2_source AS (
 SELECT concept_id FROM omop.concept WHERE vocabulary_id = 'RxNorm' AND concept_code = '313782'
),
drug2_mapped AS (
 SELECT concept_id_2 AS concept_id FROM drug2_source ds JOIN omop.concept_relationship cr ON ds.concept_id = cr.concept_id_1 WHERE cr.relationship_id = 'Maps to'
),
drug2_concepts AS (
 SELECT DISTINCT ca.descendant_concept_id AS concept_id FROM drug2_mapped dm JOIN omop.concept c ON dm.concept_id = c.concept_id JOIN omop.concept_ancestor ca ON c.concept_id = ca.ancestor_concept_id
),
drug2_exposures AS (
 SELECT de.person_id, de.drug_exposure_start_date AS start_date FROM omop.drug_exposure de JOIN drug2_concepts d2 ON de.drug_concept_id = d2.concept_id
)
SELECT COUNT(DISTINCT a.person_id) FROM drug1_exposures a JOIN drug2_exposures b ON a.person_id = b.person_id
WHERE CAST( EXTRACT(epoch FROM CAST(GREATEST(a.start_date, b.start_date) AS TIMESTAMP) - CAST(LEAST(a.start_date, b.start_date) AS TIMESTAMP) ) / 86400 AS BIGINT ) <= 30
LIMIT 1000;

