 SELECT concept_id_2 AS concept_id FROM drug_source ds JOIN omop.concept_relationship cr ON ds.concept_id = cr.concept_id_1 WHERE cr.relationship_id = 'Maps to'
),
drug_concepts AS (
 SELECT DISTINCT ca.descendant_concept_id AS concept_id FROM drug_mapped dm JOIN omop.concept c ON dm.concept_id = c.concept_id JOIN omop.concept_ancestor ca ON c.concept_id = ca.ancestor_concept_id
),
drug_exposures AS (
 SELECT de.person_id, de.drug_exposure_start_date AS event_date FROM omop.drug_exposure de JOIN drug_concepts dc ON de.drug_concept_id = dc.concept_id
)
SELECT COUNT(DISTINCT c.person_id) AS patient_count
FROM condition_occurrences c
JOIN drug_exposures d ON c.person_id = d.person_id
WHERE d.event_date > c.event_date;

